"""Curated beginner IPA practice. Existing pronunciation lessons stay unchanged."""
import json
from pathlib import Path

PATH = Path(__file__).resolve().parents[1] / 'content' / 'pronunciation.json'

def word(text, ipa, meaning, note):
    return dict(word=text, ipa=ipa, meaning=meaning, note=note)

def stage(id, title, symbols, explanation, words, bridge):
    return dict(id=id, revision=1, title=title, symbols=symbols, explanation=explanation,
                words=words, bridge=bridge,
                tasks=[dict(id=f'w{i+1}', ipa=w['ipa'], meaning=w['meaning'], answer=w['word'], explanation=w['note']) for i,w in enumerate(words)])

stages = [
stage('first-sounds', 'Буквы пишем. Звуки произносим.', ['m','s','t','i'],
      ['Посмотри на see: букв три, а звуков два — /s/ и /i/. Две буквы ee здесь обозначают один звук. Транскрипция /si/ записывает именно то, что слышно.',
       'Косые черты / / — рамка для звуков. Их не произносят. /m/, /s/, /t/ похожи на знакомые м, с, т, но английский звук сначала слушай в целом слове. /i/ — гласный в see. В другом словаре он может выглядеть как /iː/: здесь это тот же учебный ориентир.',
       'Сначала послушай четыре слова ниже. Потом по транскрипции и русскому смыслу вспомни одно из них и напечатай его английскими буквами. Угадывать незнакомое написание не нужно.'],
      [word('me','/mi/','меня; мне','/m/ + /i/ → me. Буква e здесь передаёт /i/.'),
       word('see','/si/','видеть','/s/ + /i/ → see. Две буквы ee — один гласный звук.'),
       word('meet','/mit/','встретить','К /mi/ добавился /t/. Meet заканчивается на согласный звук.'),
       word('seat','/sit/','место для сидения','/s/ + /i/ + /t/. Написание ea здесь даёт /i/.')],
      'В словаре теперь найди только рамку /…/. Не пытайся запомнить всю таблицу звуков за раз.'),
stage('ee-and-ih','/i/ и /ɪ/: seat и sit — разные слова',['ɪ','b','h'],
      ['Ты уже читал /sit/ — seat. Теперь поменяем середину: /sɪt/ — sit, «сидеть». Значок /ɪ/ — маленькая печатная I, но это другой гласный, не просто быстрое /i/.',
       'Для /ɪ/ язык чуть ниже и расслабленнее, чем для /i/. Начни со звука в записи sit. Не заменяй его русским «ы». Сравнивай целые слова, а не только длительность.',
       'Добавляем /b/ и /h/: /b/ — звонкий согласный в bit, /h/ — лёгкий выдох в hit. Не делай /h/ сильным русским «х».'],
      [word('sit','/sɪt/','сидеть','Середина /ɪ/. Если сказать /sit/, получится другое слово — seat.'),
       word('bit','/bɪt/','кусочек','/b/ + /ɪ/ + /t/. Не растягивай этот гласный в /i/.'),
       word('beat','/bit/','бить; ритм','/i/ отличает beat от bit. Длительность сама по себе не заменяет положение языка.'),
       word('hit','/hɪt/','ударить','Начало — лёгкий выдох /h/, затем /ɪ/ и /t/.')],
      'Вернись к seat и произнеси seat — sit. Затем запиши себя и сравни с двумя образцами.'),
stage('ae-and-eh','/æ/ и /ɛ/: открой рот чуть иначе',['æ','ɛ','k','p','d'],
      ['В cat середина /æ/. Открой рот шире, чем для /ɛ/ в bed; язык остаётся впереди. Это не точное русское «э» и не обычное «а». Послушай cat, затем bed.',
       'Наш /ɛ/ некоторые словари записывают /e/. Это вариант записи гласного в bed. Не путай его с /eɪ/ в day: этот звук изучим позже.',
       '/k/, /p/, /d/ — согласные в cat, cap, bed. Буква c в cat читается /k/. Транскрипция подсказывает звук независимо от буквы.'],
      [word('cat','/kæt/','кот','/k/ + /æ/ + /t/. На /æ/ челюсть опущена заметнее, чем на /ɛ/.'),
       word('cap','/kæp/','кепка','Тот же гласный /æ/, но последний звук /p/.'),
       word('bed','/bɛd/','кровать','/ɛ/ в середине. Запись /bed/ в другом словаре может обозначать этот же гласный.'),
       word('bad','/bæd/','плохой','Bed и bad различаются серединой: /ɛ/ и /æ/.')],
      'Перед новым словом ищи его гласный: /bɛd/ или /bæd/? Скажи оба слова, не торопясь.'),
stage('ah-and-uh','/ɑ/ и /ʌ/: американское hot',['ɑ','ʌ'],
      ['В американском hot буква o даёт открытый гласный /ɑ/. Не пытайся читать её по русскому названию буквы. Сравни hot /hɑt/ и уже знакомое hat /hæt/.',
       '/ʌ/ в cup — другой гласный: рот более расслаблен, язык ближе к середине. В наших односложных словах он под ударением. Безударный /ə/ появится позже.',
       'Сейчас не нужно доказывать, насколько «американски» ты звучишь. Задача — заметить значок, вспомнить образец и различить значения.'],
      [word('hot','/hɑt/','горячий','В этой американской записи /ɑ/, а не британское /ɒ/.'),
       word('hat','/hæt/','шляпа','/æ/ отличает hat от hot. Оба слова нужны для сравнения.'),
       word('cup','/kʌp/','чашка','/ʌ/ — ударный гласный в этом односложном слове.'),
       word('cut','/kʌt/','резать','Средний звук как в cup; в конце /t/, а не /p/.')],
      'Повтори цепочку hat — hot — cut. Меняется гласный, а не только громкость.'),
stage('oo-and-uh','/u/ и /ʊ/: food и foot',['u','ʊ','f','l'],
      ['Food и foot пишутся похоже, но их середина разная: /u/ и /ʊ/. Для /u/ губы обычно округляются сильнее; для /ʊ/ язык и губы расслабленнее. Слушай разницу в словах.',
       'Не своди различие к правилу «длинное и короткое у». Длительность зависит и от соседних звуков. /ʊ/ — отдельный гласный.',
       '/f/ — воздух между верхними зубами и нижней губой. /l/ — согласный в конце pool. В американской речи конечный l может звучать глубже знакомого русского л.'],
      [word('food','/fud/','еда','/u/ в середине. Иногда его записывают /uː/.'),
       word('foot','/fʊt/','ступня','/ʊ/ в середине. Одинаковые буквы oo не гарантируют одинакового звука.'),
       word('pool','/pul/','бассейн','/p/ + /u/ + /l/.'),
       word('pull','/pʊl/','тянуть','Pull и pool различаются гласным. Сначала послушай их рядом.')],
      'Выпиши две пары food — foot и pool — pull. Попробуй узнать слово по своей вчерашней записи.'),
stage('moving-vowels','/eɪ/ и /aɪ/: звук меняется внутри слога',['eɪ','aɪ'],
      ['В day гласный начинается одним положением языка и плавно меняется: /eɪ/. Это один гласный с движением, а не два отдельных слога. Такое сочетание называют дифтонгом.',
       '/aɪ/ в time тоже движется. Не вставляй паузу посередине. Слово time остаётся односложным.',
       'Смотри на два значка вместе. /eɪ/ и /aɪ/ нельзя читать так, как если бы это были два случайных звука из таблицы.'],
      [word('day','/deɪ/','день','/d/ + цельный /eɪ/. Один слог.'),
       word('date','/deɪt/','дата','Как day с конечным /t/.'),
       word('time','/taɪm/','время','/t/ + /aɪ/ + /m/. Конечная буква e отдельно не звучит.'),
       word('tie','/taɪ/','галстук','/t/ + /aɪ/. Не добавляй отдельный звук для буквы e.')],
      'Сравни bit — beat — bite /baɪt/. Последнее слово означает «кусать»: новое написание уже дано.'),
stage('more-moving-vowels','/oʊ/, /aʊ/, /ɔɪ/: ещё три движения',['oʊ','aʊ','ɔɪ','g','n'],
      ['No /noʊ/ заканчивается плавным движением /oʊ/. В американской записи обычно именно /oʊ/. В британском словаре часто увидишь /əʊ/.',
       '/aʊ/ — гласный в now, /ɔɪ/ — в boy. В каждом случае это один слог с движением языка, а не два слова.',
       '/g/ — звонкий согласный в go, /n/ — носовой согласный в no. Соедини уже знакомые согласные с новым гласным.'],
      [word('go','/goʊ/','идти','/g/ + /oʊ/.'),
       word('no','/noʊ/','нет','/n/ + /oʊ/. Не превращай слово в короткое русское «но».'),
       word('now','/naʊ/','сейчас','У no и now разная середина: /oʊ/ и /aʊ/.'),
       word('boy','/bɔɪ/','мальчик','/b/ + /ɔɪ/. Два значка гласного — одно плавное движение.')],
      'Произнеси no — now. Смысл меняется из-за одного гласного.'),
stage('schwa-and-stress','/ə/ и ˈ: какой слог сильнее',['ə','ˈ','s'],
      ['В about слышно два слога. Второй сильнее: /əˈbaʊt/. Знак ˈ стоит ПЕРЕД ударным слогом. Его не произносят. Иногда словарь ставит точки между слогами — точки тоже не звуки.',
       'Первый гласный about — /ə/, шва. Это короткий расслабленный безударный звук. Не старайся произнести чёткое русское «а» в каждом слабом слоге.',
       'Не любая неударная буква автоматически становится /ə/. Мы смотрим на словарную транскрипцию и слушаем конкретное слово. В sofa ударение в начале: /ˈsoʊfə/.'],
      [word('about','/əˈbaʊt/','о; об','Слабое /ə/, затем ударный слог /baʊt/.'),
       word('sofa','/ˈsoʊfə/','диван','Ударение на первом слоге. Последний звук — слабое /ə/.'),
       word('ago','/əˈgoʊ/','назад, о времени','Первый слог слабый, второй под ударением.'),
       word('banana','/bəˈnænə/','банан','Три слога. Только средний с /æ/ ударный, по краям /ə/.')],
      'Произнеси banana и хлопни на среднем слоге. В транскрипции найди ˈ до этого слога.'),
stage('american-r','/ɝ/ и /ɚ/: гласный с американским r',['ɝ','ɚ'],
      ['В bird американское r не исчезает. /ɝ/ обозначает ударный гласный с r-окраской: язык формирует r вместе с гласным. Это не русское раскатистое «р».',
       '/ɚ/ похож по устройству, но безударный: последний слог sister. Не пытайся сначала сказать отдельное русское «э», а затем раскатать р.',
       'Словари используют разные записи: /ɝ/ или /ɜːr/, /ɚ/ или /ər/. Это не четыре новых звука. Для начала узнавай два наших значка и слушай американский образец.'],
      [word('bird','/bɝd/','птица','/ɝ/ — ударный гласный с r-окраской.'),
       word('her','/hɝ/','её; ей, отдельное ударное слово','Это полная форма her. В быстрой фразе слово может звучать слабее.'),
       word('sister','/ˈsɪstɚ/','сестра','Первый слог ударный, в конце безударный /ɚ/.'),
       word('paper','/ˈpeɪpɚ/','бумага','/eɪ/ под ударением, /ɚ/ в слабом последнем слоге.')],
      'Скажи bird, затем sister. Заметь: r-окраска есть в обоих, а ударение устроено по-разному.'),
stage('sh-ch-j','/ʃ/, /ʒ/, /tʃ/, /dʒ/: не названия букв',['ʃ','ʒ','tʃ','dʒ','v'],
      ['/ʃ/ в ship похож на мягкое шипение; он записывает звук, который в этом слове пишется sh. /ʒ/ в vision — его звонкий сосед: добавляется голос.',
       '/tʃ/ в cheap и /dʒ/ в job начинаются с короткой смычки и переходят в шипение. Каждый такой знак-пара обозначает один слитный согласный. Не делай между частями паузу.',
       '/v/ в vision — нижняя губа у верхних зубов плюс голос. Эта запись уже не похожа на обычное написание; сверяйся по одному звуку.'],
      [word('ship','/ʃɪp/','корабль','/ʃ/ + /ɪ/ + /p/. Не путай с sheep /ʃip/ — «овца».'),
       word('cheap','/tʃip/','дешёвый','В начале цельный /tʃ/, а в середине /i/.'),
       word('job','/dʒɑb/','работа','/dʒ/ передаётся буквой j, но не называется «джей» внутри слова.'),
       word('vision','/ˈvɪʒən/','зрение; видение','/ʒ/ внутри слова звонкий. Последний гласный /ə/ слабый.')],
      'Сравни ship и cheap. Различаются и первый согласный, и гласный.'),
stage('th-and-ng','/θ/, /ð/, /ŋ/: три непривычных согласных',['θ','ð','ŋ'],
      ['Для /θ/ в thin кончик языка слегка касается края верхних зубов, воздух проходит в щель. Не смыкай губы для «ф» и не прячь язык для «с».',
       '/ð/ в this делается похожим образом, но с голосом. Положи пальцы на горло: в /ð/ должна ощущаться вибрация. Слова не обязаны звучать идеально с первого раза.',
       '/ŋ/ в sing — один носовой звук в задней части рта. В этом слове отдельного /g/ после него нет. В других словах может быть /ŋg/: проверяй транскрипцию, а не правило для всех букв ng.'],
      [word('thin','/θɪn/','тонкий','Глухой /θ/, затем /ɪ/ и /n/.'),
       word('this','/ðɪs/','этот; эта; это','В начале звонкий /ð/.'),
       word('sing','/sɪŋ/','петь','Последний звук /ŋ/. Не добавляй /g/.'),
       word('thing','/θɪŋ/','вещь','/θ/ в начале и /ŋ/ в конце. Между ними уже знакомый /ɪ/.')],
      'Запиши thin — this — sing. Сравни с образцами положение языка, а не балл распознавания речи.'),
stage('w-v-y-r','/w/, /v/, /j/, /r/: знакомые буквы могут обмануть',['w','j','r','z'],
      ['Для /w/ в west округли губы и быстро перейди к гласному. Зубы не касаются губы. Для /v/ в vest верхние зубы у нижней губы, поэтому эти слова звучат по-разному.',
       'Значок /j/ — звук в начале yes, близкий к русскому «й». Это не /dʒ/ в job и не английское название буквы J.',
       '/r/ в red здесь словарное обозначение американского r. Более точная запись согласного — [ɹ]. Язык не ударяет по нёбу как при русском р. /z/ — звонкий сосед /s/: он звучит в слове zoo, которое разберём позже.'],
      [word('west','/wɛst/','запад','/w/: губы округлены, зубы не прижаты к губе.'),
       word('vest','/vɛst/','жилет','/v/: верхние зубы у нижней губы. Остальные звуки как в west.'),
       word('yes','/jɛs/','да','В IPA /j/ — начало yes. Не читай его как /dʒ/.'),
       word('red','/rɛd/','красный','/r/ без русского раскатистого удара языка.')],
      'Найди в словаре yes и job. Теперь ты можешь объяснить, почему буква j и знак /j/ — не одно и то же.'),
stage('dictionary-variants','/ɔ/, точки и ˌ: почему словари отличаются',['ɔ','ˌ'],
      ['В law часто записывают /ɔ/. У многих американцев /ɔ/ и /ɑ/ совпадают или очень близки; у других различаются. Выбранный голос может произнести law с /ɑ/ — это допустимая особенность акцента.',
       'Точка отделяет слоги: /ˈsɪs.tɚ/. Знак ˌ отмечает второстепенное ударение, слабее главного ˈ. В afternoon /ˌæftɚˈnun/ самое заметное ударение ближе к концу.',
       'Словарная запись — удобная карта, а не запись каждого движения языка. В быстрой американской речи t внутри water может напоминать очень короткий удар языка. Обозначения такого варианта разберём в занятиях о связной речи.'],
      [word('law','/lɔ/','закон','Здесь используется /ɔ/. В речи слияние /ɔ/ и /ɑ/ не ошибка.'),
       word('author','/ˈɔθɚ/','автор','Первый слог ударный; /θ/ без голоса; последний /ɚ/ слабый.'),
       word('afternoon','/ˌæftɚˈnun/','время после полудня','ˌ — второстепенное ударение, ˈ — главное перед /nun/.'),
       word('zoo','/zu/','зоопарк','/z/ с голосом и /u/. Буквы oo передают один гласный.')],
      'Открой US-запись одного слова в двух словарях. Найди главное ударение и гласный, даже если оформление отличается.'),
stage('read-a-short-phrase','Прочитай целую короткую фразу',[' '],
      ['Теперь соберём знакомые слова. Пробелы помогают видеть границы: /aɪ æm/ — I am. Слово am /æm/ дано здесь впервые: «являюсь», часть фразы о себе.',
       'Ниже полные, чёткие формы для чтения. В разговоре I am часто сокращается до I’m /aɪm/. Значение сохраняется, звуков становится меньше.',
       'Сначала вспомни фразу по звукам, потом прослушай и повтори. В этом тренажёре проверяется только написанный ответ. Как звучит твой голос, сравни по записи самостоятельно.'],
      [word('I am','/aɪ æm/','я; я являюсь, полная форма','I /aɪ/ + am /æm/. Два отдельных слова.'),
       word("I'm",'/aɪm/','я; я являюсь, сокращённая форма','I am сократилось до I’m. Апостроф показывает сокращение.'),
       word('see me','/si mi/','увидеть меня','Два уже известных слова со звуком /i/.'),
       word('meet me','/mit mi/','встретить меня','У meet есть конечный /t/, у me его нет.')],
      'Дальше переходи к основным занятиям произношения: окончания, ударение, связная речь. Возвращайся к значкам по мере появления новых слов.')
]

catalog = json.loads(PATH.read_text(encoding='utf-8'))
catalog['decoder'] = dict(title='Транскрипция с нуля', description='14 коротких ступеней: от /si/ до целой фразы. Сначала разбор и звук, затем твой ответ, после — образец и повторение.', stages=stages)
catalog['description'] = 'Начни с 14 коротких ступеней чтения IPA, затем переходи к 16 занятиям произношения и связной речи. Основная опора — американский английский. Символы учим на знакомых словах, слушаем образец и сравниваем свою запись. Региональные варианты допустимы: цель — понятная речь.'
for source in [
    dict(title='Rachel’s English — видео и расшифровка: schwa /ə/', url='https://rachelsenglish.com/english-pronounce-schwa/'),
    dict(title='Rachel’s English — американские гласные и дифтонги: каталог видео', url='https://rachelsenglish.com/video-categories/'),
]:
    if not any(s['url']==source['url'] for s in catalog['sources']): catalog['sources'].append(source)
PATH.write_bytes((json.dumps(catalog,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
print(f'IPA decoder: {len(stages)} stages, {sum(len(s["tasks"]) for s in stages)} typed tasks')
